require('dotenv').config();
const http=require('http'),fs=require('fs'),path=require('path'),crypto=require('crypto');
const nodemailer=require('nodemailer');
const {Pool}=require('pg');
const PORT=Number(process.env.PORT||3000),ROOT=__dirname,PUB=path.join(ROOT,'public'),DB=process.env.DATABASE_URL,SESSION_HOURS=12;
const PUBLIC_HOST=String(process.env.PUBLIC_HOST||'').toLowerCase().replace(/^https?:\/\//,'').replace(/\/$/,'');
const CONTROL_HOST=String(process.env.CONTROL_HOST||'').toLowerCase().replace(/^https?:\/\//,'').replace(/\/$/,'');
function requestHost(req){return String(req.headers['x-forwarded-host']||req.headers.host||'').split(',')[0].trim().toLowerCase().split(':')[0]}
function hostMode(req){return 'control'}
if(!DB){console.error('DATABASE_URL tanımlı değil');process.exit(1)}
const internal=/railway\.internal/i.test(DB);const ssl=process.env.DATABASE_SSL==='true'||(process.env.DATABASE_SSL!=='false'&&!internal&&process.env.NODE_ENV==='production');
const pool=new Pool({connectionString:DB,ssl:ssl?{rejectUnauthorized:false}:false,max:10,connectionTimeoutMillis:10000});let databaseReady=false,databaseError=null;
const resetAttempts=new Map();
function clientIp(req){return String(req.headers['x-forwarded-for']||req.socket.remoteAddress||'unknown').split(',')[0].trim()}
function resetRateAllowed(req){const key=clientIp(req),now=Date.now(),windowMs=15*60*1000,max=5;let list=(resetAttempts.get(key)||[]).filter(t=>now-t<windowMs);if(list.length>=max){resetAttempts.set(key,list);return false}list.push(now);resetAttempts.set(key,list);return true}
setInterval(()=>{const now=Date.now();for(const [k,v] of resetAttempts){const n=v.filter(t=>now-t<15*60*1000);if(n.length)resetAttempts.set(k,n);else resetAttempts.delete(k)}},10*60*1000).unref();
const clean=(v,m=500)=>String(v||'').trim().slice(0,m),slugify=v=>clean(v,80).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(v),validTime=v=>/^([01]\d|2[0-3]):[0-5]\d$/.test(v);
function hash(p,s){return crypto.scryptSync(p,s,64).toString('hex')}
const tokenHash=t=>crypto.createHash('sha256').update(String(t)).digest('hex');
function publicBaseUrl(req){const configured=clean(process.env.APP_URL||'https://control.atabari.live',500).replace(/\/$/,'');if(configured)return configured;const proto=req.headers['x-forwarded-proto']||'http';return `${proto}://${req.headers.host}`;}
function mailTransport(){if(!process.env.SMTP_HOST||!process.env.SMTP_USER||!process.env.SMTP_PASS)return null;return nodemailer.createTransport({host:process.env.SMTP_HOST,port:Number(process.env.SMTP_PORT||587),secure:String(process.env.SMTP_SECURE||'false')==='true',auth:{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS},tls:{rejectUnauthorized:String(process.env.SMTP_TLS_REJECT_UNAUTHORIZED||'true')!=='false'}})}
function emailFrame(title,content){return `<div style="background:#0b0b0d;padding:32px 12px;font-family:Arial,sans-serif;color:#fff"><div style="max-width:580px;margin:auto;background:#151518;border:1px solid #2b2b31;border-radius:18px;overflow:hidden"><div style="padding:22px 26px;border-bottom:3px solid #e52b24"><div style="font-size:13px;color:#aaa;letter-spacing:2px">ATABARI CONTROL CENTER</div><h2 style="margin:8px 0 0;color:#fff">${title}</h2></div><div style="padding:26px;line-height:1.65">${content}</div><div style="padding:18px 26px;background:#101012;color:#777;font-size:12px">Bu e-posta ATABARI Control Center tarafından otomatik gönderilmiştir.</div></div></div>`}
async function sendMail({to,subject,text,html}){const tr=mailTransport();if(!tr)throw new Error('E-posta servisi yapılandırılmadı.');return tr.sendMail({from:process.env.EMAIL_FROM||process.env.SMTP_USER,to,subject,text,html})}
async function sendResetEmail(to,link){await sendMail({to,subject:'ATABARI - Şifre sıfırlama bağlantısı',text:`Şifrenizi sıfırlamak için bağlantıyı açın: ${link}\n\nBağlantı 30 dakika geçerlidir ve yalnızca bir kez kullanılabilir.`,html:emailFrame('Şifre Sıfırlama Talebi',`<p>Hesabınızın şifresini yenilemek için aşağıdaki butona tıklayın.</p><p style="margin:26px 0"><a href="${link}" style="display:inline-block;padding:13px 20px;background:#e52b24;color:#fff;text-decoration:none;border-radius:10px;font-weight:700">Şifremi Sıfırla</a></p><p style="color:#aaa">Bu bağlantı <b>30 dakika</b> geçerlidir ve yalnızca bir kez kullanılabilir.</p><p style="color:#777;font-size:13px">Bu talebi siz oluşturmadıysanız e-postayı yok sayabilirsiniz.</p>`)})}
async function sendPasswordChangedEmail(to,when){if(!to)return;await sendMail({to,subject:'ATABARI - Şifreniz değiştirildi',text:`Hesabınızın şifresi ${when} tarihinde değiştirildi. Bu işlemi siz yapmadıysanız yöneticinizle hemen iletişime geçin.`,html:emailFrame('Şifre Değişikliği Bildirimi',`<p>Hesabınızın şifresi <b>${when}</b> tarihinde değiştirildi.</p><p>Bu işlemi siz yapmadıysanız yöneticinizle hemen iletişime geçin.</p>`)})}
async function sendTestEmail(to){await sendMail({to,subject:'ATABARI - SMTP test e-postası',text:'SMTP ayarlarınız başarıyla çalışıyor.',html:emailFrame('E-posta Sistemi Çalışıyor',`<p>Bu test mesajını görüyorsanız Natro/SMTP bağlantınız başarıyla yapılandırılmıştır.</p><p style="color:#aaa">Artık şifre sıfırlama ve güvenlik bildirimleri otomatik gönderilebilir.</p>`)})}
async function sendSponsorReminderEmail(to,r){if(!to)return;const list=Array.isArray(r.checklist)?r.checklist:[];await sendMail({to,subject:`Sponsor hatırlatması: ${r.brand_name}`,text:`${r.brand_name} - ${r.title}\n\n${r.message||''}\nKod: ${r.promo_code||'-'}\nLink: ${r.promo_link||'-'}`,html:emailFrame('Sponsor Hatırlatması',`<p><b>${r.brand_name}</b> · ${r.title}</p><p>${r.message||'Sponsor görev zamanı geldi.'}</p>${r.promo_code?`<p><b>Kod:</b> ${r.promo_code}</p>`:''}${r.promo_link?`<p><a href="${r.promo_link}" style="color:#ff6158">Sponsor bağlantısını aç</a></p>`:''}${list.length?`<ul>${list.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}`)})}
function json(res,c,o,h={}){res.writeHead(c,{'Content-Type':'application/json; charset=utf-8',...h});res.end(JSON.stringify(o))}
function body(req){return new Promise((ok,no)=>{let d='';req.on('data',c=>{d+=c;if(d.length>500000){no(new Error('İstek çok büyük'));req.destroy()}});req.on('end',()=>{try{ok(d?JSON.parse(d):{})}catch(e){no(e)}})})}
function cookies(req){return Object.fromEntries((req.headers.cookie||'').split(';').filter(Boolean).map(x=>{let i=x.indexOf('=');return[x.slice(0,i).trim(),decodeURIComponent(x.slice(i+1))]}))}
function serve(res,file){if(!fs.existsSync(file)){res.writeHead(404);return res.end('Not found')}const ext=path.extname(file),types={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'application/javascript; charset=utf-8','.png':'image/png','.svg':'image/svg+xml','.ico':'image/x-icon'};res.writeHead(200,{'Content-Type':types[ext]||'application/octet-stream','X-Content-Type-Options':'nosniff'});fs.createReadStream(file).pipe(res)}
