async function processSponsorReminders(){if(!databaseReady)return;try{let r=await pool.query(`SELECT sr.*,st.title,s.brand_name,u.email FROM sponsor_reminders sr JOIN sponsor_tasks st ON st.id=sr.sponsor_task_id JOIN sponsors s ON s.id=st.sponsor_id LEFT JOIN users u ON u.streamer_id=sr.streamer_id AND u.role='streamer' AND u.active=TRUE WHERE sr.status IN ('pending','snoozed') AND sr.remind_at<=NOW() AND sr.notified_at IS NULL ORDER BY sr.remind_at LIMIT 20`);for(const x of r.rows){try{if(x.email&&mailTransport())await sendSponsorReminderEmail(x.email,x);await pool.query("UPDATE sponsor_reminders SET status='notified',notified_at=NOW(),updated_at=NOW() WHERE id=$1",[x.id])}catch(e){console.error('Sponsor hatırlatma e-postası:',e.message)}}}catch(e){console.error('Sponsor hatırlatıcı işleyici:',e.message)}}
setInterval(processSponsorReminders,60000).unref();
async function init(){let n=0;while(!databaseReady){n++;try{await migrate();databaseReady=true;console.log('PostgreSQL hazır')}catch(e){databaseError=e;console.error('DB denemesi',n,e.message);await new Promise(r=>setTimeout(r,Math.min(30000,n*5000)))}}}server.listen(PORT,'0.0.0.0',()=>{console.log('ATABARI',PORT);init()});
